import { useMemo } from 'react'
import {
  EuiPanel,
  EuiTitle,
  EuiFlexGroup,
  EuiFlexItem,
  EuiText,
  EuiSpacer,
  EuiProgress,
  EuiBadge,
  EuiLoadingSpinner,
  EuiHealth,
} from '@elastic/eui'
import {
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
  Tooltip,
} from 'recharts'
import { useMoEIntelligence } from '../../../hooks/useDashboardData'

const COLORS = ['#006BB4', '#00BFB3', '#F5A700', '#BD271E', '#98A2B3']

const MoERoutingViz = () => {
  const { data, loading, error } = useMoEIntelligence()

  const routingData = useMemo(() => {
    if (!data?.routing_patterns) return []

    return Object.entries(data.routing_patterns).map(([master, stats]: [string, any]) => ({
      name: master.replace('-master', ''),
      value: stats.task_count || 0,
      confidence: stats.avg_confidence || 0,
    }))
  }, [data])

  const recentDecisions = useMemo(() => {
    if (!data?.recent_decisions) return []
    return data.recent_decisions.slice(0, 5)
  }, [data])

  if (loading) {
    return (
      <EuiPanel hasBorder>
        <EuiFlexGroup justifyContent="center" alignItems="center" style={{ height: 300 }}>
          <EuiFlexItem grow={false}>
            <EuiLoadingSpinner size="l" />
          </EuiFlexItem>
        </EuiFlexGroup>
      </EuiPanel>
    )
  }

  if (error) {
    return (
      <EuiPanel hasBorder>
        <EuiTitle size="s"><h3>MoE Routing Intelligence</h3></EuiTitle>
        <EuiText color="danger"><p>Error: {error}</p></EuiText>
      </EuiPanel>
    )
  }

  return (
    <EuiPanel hasBorder>
      <EuiTitle size="s"><h3>MoE Routing Intelligence</h3></EuiTitle>
      <EuiSpacer size="m" />

      <EuiFlexGroup>
        <EuiFlexItem>
          <EuiText size="s"><strong>Expert Distribution</strong></EuiText>
          <ResponsiveContainer width="100%" height={200}>
            <PieChart>
              <Pie
                data={routingData}
                dataKey="value"
                nameKey="name"
                cx="50%"
                cy="50%"
                outerRadius={70}
                label={({ name, percent }) =>
                  `${name} ${((percent || 0) * 100).toFixed(0)}%`
                }
                labelLine={false}
              >
                {routingData.map((_, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </EuiFlexItem>

        <EuiFlexItem>
          <EuiText size="s"><strong>Confidence Scores</strong></EuiText>
          <EuiSpacer size="s" />
          {routingData.map((item, index) => (
            <div key={item.name} style={{ marginBottom: 8 }}>
              <EuiFlexGroup justifyContent="spaceBetween" alignItems="center">
                <EuiFlexItem grow={false}>
                  <EuiText size="xs">{item.name}</EuiText>
                </EuiFlexItem>
                <EuiFlexItem grow={false}>
                  <EuiText size="xs">{(item.confidence * 100).toFixed(0)}%</EuiText>
                </EuiFlexItem>
              </EuiFlexGroup>
              <EuiProgress
                value={item.confidence * 100}
                max={100}
                size="s"
                color={COLORS[index % COLORS.length]}
              />
            </div>
          ))}
        </EuiFlexItem>
      </EuiFlexGroup>

      <EuiSpacer size="m" />
      <EuiText size="s"><strong>Recent Decisions</strong></EuiText>
      <EuiSpacer size="s" />

      {recentDecisions.map((decision: any, index: number) => (
        <div key={index} style={{ marginBottom: 8, padding: 8, background: '#f5f7fa', borderRadius: 4 }}>
          <EuiFlexGroup justifyContent="spaceBetween" alignItems="center">
            <EuiFlexItem grow={false}>
              <EuiBadge color="primary">{decision.selected_expert}</EuiBadge>
            </EuiFlexItem>
            <EuiFlexItem grow={false}>
              <EuiHealth color={decision.confidence > 0.7 ? 'success' : 'warning'}>
                {(decision.confidence * 100).toFixed(0)}%
              </EuiHealth>
            </EuiFlexItem>
          </EuiFlexGroup>
          <EuiText size="xs" color="subdued">
            {decision.task_id}: {decision.task_description?.substring(0, 50)}...
          </EuiText>
        </div>
      ))}
    </EuiPanel>
  )
}

export default MoERoutingViz
